        "taskDecomposer": "/decomposeTask"
      },
      {
        "toolNavigator": "/navigateTools"
      },
      {
        "taskExecutor": "/executeTask"
      },
      {
        "testVerifier": "/verifyResult"
      },
      {
        "learningSystem": "/learnFromTask"
      }
    ]
  }
}

